HISTORIES.push(...[{"id":"poster-europe-001","title":"Iron Age Britain · Celtic-speaking communities","shortTitle":"Celtic Era","region":"europe","dates":"800 BC–43 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Selected pre-Roman Iron Age frame; Celtic languages and identities did not disappear in 43 AD. Stonehenge belongs to the much earlier Neolithic and Bronze Age, rather than to the origin of a Celtic state.","wikiTitle":"Iron Age Britain","parent":null,"category":"history","sources":["poster_poster-europe-001_0","poster_poster-europe-001_1","wikipedia_poster-europe-001"],"posterLabels":["Celtic Era"],"start":-800,"end":43,"ongoing":false,"graphOnly":false},{"id":"poster-europe-002","title":"Lusitanians and neighbouring Iron Age communities","shortTitle":"Lusitanians and Other Tribes","region":"europe","dates":"600 BC–139 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"An approximate Iron Age frame, not a single kingdom founded in 600 BC. Roman writers attest Lusitanians later; the Lusitanian War ended in 139 BC but regional conquest continued.","wikiTitle":"Lusitanians","parent":null,"category":"history","sources":["poster_poster-europe-002_0","wikipedia_poster-europe-002"],"posterLabels":["Lusitanians and Other Tribes"],"start":-600,"end":-139,"ongoing":false,"graphOnly":false},{"id":"poster-europe-003","title":"Iberian and Celtiberian communities","shortTitle":"Iberian & Celtic Tribes","region":"europe","dates":"600 BC–19 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A broad grouping of distinct peoples, languages and regional societies. Iberian culture is usually identified from the first millennium BC; Rome completed its wider Iberian conquests in 19 BC, not in 218 BC.","wikiTitle":"Iberians","parent":null,"category":"history","sources":["poster_poster-europe-003_0","wikipedia_poster-europe-003"],"posterLabels":["Iberian & Celtic Tribes"],"start":-600,"end":-19,"ongoing":false,"graphOnly":false},{"id":"poster-europe-004","title":"Carthaginian Iberia · Barcid expansion","shortTitle":"Punic Iberia","region":"europe","dates":"237 BC–206 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Selected Barcid territorial phase beginning with Hamilcar Barca in 237 BC. Phoenician and Punic settlements predate it; Rome expelled the main Carthaginian forces from Iberia in 206 BC.","wikiTitle":"Carthaginian Iberia","parent":null,"category":"history","sources":["poster_poster-europe-004_0","wikipedia_poster-europe-004"],"posterLabels":["Carthaginian Era"],"start":-237,"end":-206,"ongoing":false,"graphOnly":false},{"id":"poster-europe-005","title":"Gaul · Iron Age communities","shortTitle":"Gaul","region":"europe","dates":"800 BC–50 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"An approximate regional Iron Age frame, not one Celtic state. Caesar campaigned in 58–50 BC; southern Gaul had already come under Roman rule.","wikiTitle":"Gaul","parent":null,"category":"history","sources":["poster_poster-europe-005_0","wikipedia_poster-europe-005"],"posterLabels":["Gaul"],"start":-800,"end":-50,"ongoing":false,"graphOnly":false},{"id":"poster-europe-006","title":"Italic peoples · early Italian peninsula","shortTitle":"Italic Tribes","region":"europe","dates":"1200 BC–500 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"An approximate early grouping of several languages and peoples. Etruscans were not linguistically Italic, Greek colonies were distinct, and Italic communities continued after the Roman monarchy began.","wikiTitle":"Italic peoples","parent":null,"category":"history","sources":["poster_poster-europe-006_0","wikipedia_poster-europe-006"],"posterLabels":["Italic Tribes"],"start":-1200,"end":-500,"ongoing":false,"graphOnly":false},{"id":"poster-europe-007","title":"Roman Kingdom · traditional chronology","shortTitle":"Roman Kingdom","region":"europe","dates":"753 BC–509 BC","type":"Political or archaeological frame","status":"Debated","location":"Europe","summary":"","note":"753 BC and 509 BC are traditional foundation and transition dates transmitted by later Roman historians, not archaeologically proven day-one boundaries.","wikiTitle":"Roman Kingdom","parent":null,"category":"history","sources":["poster_poster-europe-007_0","wikipedia_poster-europe-007"],"posterLabels":["Roman Kingdom"],"start":-753,"end":-509,"ongoing":false,"graphOnly":false},{"id":"poster-europe-011","title":"Central European Celtic and Germanic communities","shortTitle":"Celtic & Germanic Tribes","region":"europe","dates":"800 BC–400 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A regional, approximate cultural frame spanning many communities. These categories are linguistic and historical labels, not one government or an unbroken ethnic ancestry.","wikiTitle":"Iron Age Europe","parent":null,"category":"history","sources":["poster_poster-europe-011_0","wikipedia_poster-europe-011"],"posterLabels":["Celtic & Germanic Tribes"],"start":-800,"end":400,"ongoing":false,"graphOnly":false},{"id":"poster-europe-012","title":"Hallstatt culture · early Iron Age phases","shortTitle":"Hallstatt Culture","region":"europe","dates":"800 BC–450 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The selected Iron Age Hallstatt C–D phases date approximately 800–450 BC. Broader Hallstatt A–B material belongs to the earlier Bronze Age; the culture was not a unitary state.","wikiTitle":"Hallstatt culture","parent":null,"category":"history","sources":["poster_poster-europe-012_0","poster_poster-europe-012_1","wikipedia_poster-europe-012"],"posterLabels":["Hallstatt Culture"],"start":-800,"end":-450,"ongoing":false,"graphOnly":false},{"id":"poster-europe-013","title":"Kingdom of Noricum","shortTitle":"Celtic Kingdom of Noricum","region":"europe","dates":"200 BC–15 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Norican kingdom or federation consolidated around the second century BC; the poster’s c. 400 BC better describes earlier regional Celtic culture. Roman annexation began in 15 BC; later provincial institutions continued.","wikiTitle":"Regnum Noricum","parent":null,"category":"history","sources":["poster_poster-europe-013_0","wikipedia_poster-europe-013"],"posterLabels":["Celtic Kingdom of Noricum"],"start":-200,"end":-15,"ongoing":false,"graphOnly":false},{"id":"poster-europe-014","title":"Aegean Bronze Age cultures","shortTitle":"Aegean Civilizations","region":"europe","dates":"3200 BC–1100 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"An archaeological umbrella including Cycladic, Minoan and Mycenaean cultures with different chronologies; it was not one empire or an exclusive origin story for later Greeks.","wikiTitle":"Aegean civilization","parent":null,"category":"history","sources":["poster_poster-europe-014_0","wikipedia_poster-europe-014"],"posterLabels":["Aegean Civilizations"],"start":-3200,"end":-1100,"ongoing":false,"graphOnly":false},{"id":"poster-europe-018","title":"Early Iron Age Greece · Greek Dark Ages","shortTitle":"Greek Dark Age","region":"europe","dates":"1100 BC–800 BC","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A conventional archaeological period following palace collapse. The label does not imply an absence of communities, creativity or contact; boundaries vary between regions.","wikiTitle":"Greek Dark Ages","parent":null,"category":"history","sources":["poster_poster-europe-018_0","wikipedia_poster-europe-018"],"posterLabels":["Greek Dark Age"],"start":-1100,"end":-800,"ongoing":false,"graphOnly":false},{"id":"poster-europe-025","title":"Sub-Roman Britain","shortTitle":"Sub-Roman Britain","region":"europe","dates":"410 AD–600 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Approximate transition after the withdrawal of Roman imperial administration, conventionally around 410. Regional British polities continued alongside incoming and established communities; 500 is not a universal end date.","wikiTitle":"Sub-Roman Britain","parent":null,"category":"history","sources":["poster_poster-europe-025_0","wikipedia_poster-europe-025"],"posterLabels":["Sub-Roman Britain"],"start":410,"end":600,"ongoing":false,"graphOnly":false},{"id":"poster-europe-035","title":"First County of Portugal","shortTitle":"First County of Portugal","region":"europe","dates":"868 AD–1071 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A conventional first-county frame beginning with the recovery of Porto in 868. The first comital line ended with Nuno Mendes’s defeat in 1071. Royal administration and later reorganisation preceded Henry of Burgundy’s county around 1096; this was not an uninterrupted independent state.","wikiTitle":"County of Portugal","parent":null,"category":"history","sources":["poster_poster-europe-035_0","poster_poster-europe-035_1","wikipedia_poster-europe-035"],"posterLabels":["First County of Portugal"],"start":868,"end":1071,"ongoing":false,"graphOnly":false},{"id":"poster-europe-036","title":"Second County of Portugal","shortTitle":"Portucale II","region":"europe","dates":"1096 AD–1139 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The second county is usually dated from Henry of Burgundy’s appointment around 1096. Afonso Henriques’ kingship in 1139 and recognition in 1143 and 1179 mark different steps toward independence.","wikiTitle":"County of Portugal","parent":null,"category":"history","sources":["poster_poster-europe-036_0","wikipedia_poster-europe-036"],"posterLabels":["Second County of Portugal"],"start":1096,"end":1139,"ongoing":false,"graphOnly":false},{"id":"cn-portugal","title":"Kingdom of Portugal","region":"europe","dates":"1139–1910 AD","wikiTitle":"Kingdom of Portugal","location":"Europe","note":"A long political frame with dynastic and constitutional changes, including the Iberian Union of 1580–1640. The colonial link shown here is a selected episode.","summary":"","status":"Debated","type":"Political or archaeological frame","sources":["poster_cn-portugal_0","wikipedia_cn-portugal"],"graphOnly":false,"shortTitle":"Kingdom of Portugal","parent":null,"category":"history","posterLabels":["Kingdom of Portugal"],"start":1139,"end":1910,"ongoing":false},{"id":"portugalmodern","title":"Portugal · modern republican eras","shortTitle":"Portugal","region":"europe","dates":"1910 AD–present","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A modern country frame including the First Republic, military and Estado Novo dictatorships, and the democratic transition. Democracy began after 1974; the present constitution took effect in 1976.","wikiTitle":"History of Portugal","parent":null,"category":"history","sources":["poster_portugalmodern_0","poster_portugalmodern_1","wikipedia_portugalmodern"],"posterLabels":["Portugal"],"start":1910,"end":2027,"ongoing":true,"graphOnly":false},{"id":"poster-europe-045","title":"Kingdom of the Suebi","shortTitle":"Suebi Kingdom","region":"europe","dates":"409 AD–585 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Suebi established rule in northwestern Iberia after crossing the Rhine and entering Iberia. The Visigoths annexed their kingdom in 585; this was not a kingdom encompassing all Iberia.","wikiTitle":"Kingdom of the Suebi","parent":null,"category":"history","sources":["poster_poster-europe-045_0","wikipedia_poster-europe-045"],"posterLabels":["Suebi Kingdom"],"start":409,"end":585,"ongoing":false,"graphOnly":false},{"id":"poster-europe-046","title":"Visigothic Kingdom","shortTitle":"Visigothic Kingdom","region":"europe","dates":"418 AD–711 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The kingdom began in Aquitaine in 418 and shifted toward Iberia. The Suebi were annexed in 585; Byzantine-controlled southern areas remained separate until the seventh century. After 711, remnants continued in Septimania into the 720s.","wikiTitle":"Visigothic Kingdom","parent":null,"category":"history","sources":["poster_poster-europe-046_0","wikipedia_poster-europe-046"],"posterLabels":["Visigothic Kingdom"],"start":418,"end":711,"ongoing":false,"graphOnly":false},{"id":"poster-europe-047","title":"Al-Andalus","shortTitle":"Al-Andalus","region":"europe","dates":"711 AD–1492 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"An umbrella for changing Muslim-ruled Iberian territories, not a single state lasting throughout 711–1492. The emirate, caliphate, taifas and later dynasties overlap with northern Christian kingdoms.","wikiTitle":"Al-Andalus","parent":null,"category":"history","sources":["poster_poster-europe-047_0","wikipedia_poster-europe-047"],"posterLabels":["Al-Andalus"],"start":711,"end":1492,"ongoing":false,"graphOnly":false},{"id":"poster-europe-048","title":"Kingdom of Asturias","shortTitle":"Kingdom of Asturias","region":"europe","dates":"718 AD–924 AD","type":"Political or archaeological frame","status":"Debated","location":"Europe","summary":"","note":"718 is a traditional royal origin date. The court and political centre shifted to León in 910, while distinct Asturian royal claims continued to 924; chronology depends on whether one tracks title, court or territory.","wikiTitle":"Kingdom of Asturias","parent":null,"category":"history","sources":["poster_poster-europe-048_0","wikipedia_poster-europe-048"],"posterLabels":["Kingdom of Asturias"],"start":718,"end":924,"ongoing":false,"graphOnly":false},{"id":"poster-europe-049","title":"Kingdom of León","shortTitle":"Kingdom of León","region":"europe","dates":"910 AD–1230 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A selected independent royal frame. León and Castile were joined and separated at several points; permanent dynastic union in 1230 did not erase León’s regional institutions.","wikiTitle":"Kingdom of León","parent":null,"category":"history","sources":["poster_poster-europe-049_0","wikipedia_poster-europe-049"],"posterLabels":["Kingdom of León"],"start":910,"end":1230,"ongoing":false,"graphOnly":false},{"id":"poster-europe-058","title":"Frankish realms · Merovingian and Carolingian periods","shortTitle":"Frankish Kingdom","region":"europe","dates":"481 AD–843 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"481 marks Clovis I’s accession, not the first existence of Franks. Frankish realms were repeatedly divided; imperial coronation in 800 and partition in 843 are distinct events.","wikiTitle":"Francia","parent":null,"category":"history","sources":["poster_poster-europe-058_0","wikipedia_poster-europe-058"],"posterLabels":["Frankish Kingdom"],"start":481,"end":843,"ongoing":false,"graphOnly":false},{"id":"cn-westfrancia","title":"West Francia","region":"europe","dates":"843–987 AD · selected frame","wikiTitle":"West Francia","location":"Europe","note":"A kingdom created by the partition of 843. The Capetian accession in 987 is a dynastic convention, not an instant creation of French society.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-westfrancia_0","wikipedia_cn-westfrancia"],"graphOnly":false,"shortTitle":"West Francia","parent":null,"category":"history","posterLabels":["West Francia"],"start":843,"end":987,"ongoing":false},{"id":"cn-westrome","title":"Western Roman Empire · late phase","region":"europe","dates":"395–476 AD · selected phase","wikiTitle":"Western Roman Empire","location":"Europe","note":"The selected late phase follows the 395 division of imperial courts. Roman institutions and communities did not disappear in 476.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-westrome_0","wikipedia_cn-westrome"],"graphOnly":false,"shortTitle":"Western Rome","parent":null,"category":"history","posterLabels":["Western Roman Empire"],"start":395,"end":476,"ongoing":false},{"id":"poster-europe-072","title":"Ostrogothic Kingdom in Italy","shortTitle":"Ostrogothic Kingdom","region":"europe","dates":"493 AD–553 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Theodoric took control of Italy in 493. 553 is a conventional endpoint after Byzantine victories; warfare and residual resistance continued.","wikiTitle":"Ostrogothic Kingdom","parent":null,"category":"history","sources":["poster_poster-europe-072_0","poster_poster-europe-072_1","wikipedia_poster-europe-072"],"posterLabels":["Ostrogothic Kingdom"],"start":493,"end":553,"ongoing":false,"graphOnly":false},{"id":"poster-europe-074","title":"Kingdom of the Lombards","shortTitle":"Lombard Kingdom","region":"europe","dates":"568 AD–774 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Lombard kingdom ruled much of the peninsula after 568 and was conquered by Charlemagne in 774. Southern Lombard duchies continued afterward.","wikiTitle":"Kingdom of the Lombards","parent":null,"category":"history","sources":["poster_poster-europe-074_0","poster_poster-europe-074_1","wikipedia_poster-europe-074"],"posterLabels":["Lombard Kingdom"],"start":568,"end":774,"ongoing":false,"graphOnly":false},{"id":"poster-europe-075","title":"Italian states · medieval communes and regional powers","shortTitle":"Medieval Italian States","region":"europe","dates":"774 AD–1494 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A regional umbrella for many states, cities and jurisdictions, not one state. Venice, Genoa, the Papal States, imperial territories and southern kingdoms had distinct histories.","wikiTitle":"Italy in the Middle Ages","parent":null,"category":"history","sources":["poster_poster-europe-075_0","wikipedia_poster-europe-075"],"posterLabels":["Medieval Italian States"],"start":774,"end":1494,"ongoing":false,"graphOnly":false},{"id":"poster-europe-076","title":"Kingdom of Sicily","shortTitle":"Kingdom of Sicily","region":"europe","dates":"1130 AD–1816 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Founded in 1130. After 1282 the island and mainland crowns were politically divided, with both claiming Sicilian titles; they were formally combined as the Two Sicilies in 1816. The poster’s 1494 boundary is not the kingdom’s end.","wikiTitle":"Kingdom of Sicily","parent":null,"category":"history","sources":["poster_poster-europe-076_0","wikipedia_poster-europe-076"],"posterLabels":["Kingdom of Sicily"],"start":1130,"end":1816,"ongoing":false,"graphOnly":false},{"id":"poster-europe-078","title":"Kingdom of the Two Sicilies","shortTitle":"Two Sicilies","region":"europe","dates":"1816 AD–1861 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The poster’s 1815 restoration relates to the post-Napoleonic settlement. The unified Kingdom of the Two Sicilies was formally created in 1816 and incorporated into the Kingdom of Italy in 1861.","wikiTitle":"Kingdom of the Two Sicilies","parent":null,"category":"history","sources":["poster_poster-europe-078_0","wikipedia_poster-europe-078"],"posterLabels":["Bourbon Sicily"],"start":1816,"end":1861,"ongoing":false,"graphOnly":false},{"id":"poster-europe-082","title":"Germanic-speaking communities in late antiquity","shortTitle":"Germanic peoples","region":"europe","dates":"375 AD–568 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A selected late antique migration frame encompassing many groups and political formations. Language labels do not imply one people, one kingdom or an unbroken ancestry for modern Germany.","wikiTitle":"Germanic peoples","parent":null,"category":"history","sources":["poster_poster-europe-082_0","wikipedia_poster-europe-082"],"posterLabels":["Germanic Tribes"],"start":375,"end":568,"ongoing":false,"graphOnly":false},{"id":"poster-europe-083","title":"Migration Period · late antique Europe","shortTitle":"Migration Period","region":"europe","dates":"300 AD–800 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A broad conventional span used by the Metropolitan Museum; other historians use narrower fourth-to-sixth-century ranges. Migration involved warfare, settlement, Roman service and changing identities rather than a single population replacement.","wikiTitle":"Migration Period","parent":null,"category":"history","sources":["poster_poster-europe-083_0","poster_poster-europe-083_1","wikipedia_poster-europe-083"],"posterLabels":["Migration Period"],"start":300,"end":800,"ongoing":false,"graphOnly":false},{"id":"poster-europe-084","title":"Post-Roman kingdoms in the eastern Alpine region","shortTitle":"Alpine kingdoms","region":"europe","dates":"476 AD–568 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A selected regional transition among successor authorities, including Ostrogothic influence and emerging Bavarian power. It is not a single named kingdom founded in 476.","wikiTitle":"Early Middle Ages","parent":null,"category":"history","sources":["poster_poster-europe-084_0","wikipedia_poster-europe-084"],"posterLabels":["Post-Roman Germanic Kingdoms"],"start":476,"end":568,"ongoing":false,"graphOnly":false},{"id":"poster-europe-085","title":"Early Duchy of Bavaria","shortTitle":"Duchy of Bavaria","region":"europe","dates":"555 AD–788 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The first Bavarian duchy is conventionally traced to the mid-sixth century; Charlemagne deposed Tassilo III in 788. Later Bavarian duchies continued under different political arrangements.","wikiTitle":"Duchy of Bavaria","parent":null,"category":"history","sources":["poster_poster-europe-085_0","wikipedia_poster-europe-085"],"posterLabels":["Duchy of Bavaria"],"start":555,"end":788,"ongoing":false,"graphOnly":false},{"id":"cn-eastfrancia","title":"East Francia","region":"europe","dates":"843–962 AD · selected frame","wikiTitle":"East Francia","location":"Europe","note":"The map selects the kingdom before Otto I’s imperial coronation. The kingdom and later empire developed through successive changes.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-eastfrancia_0","wikipedia_cn-eastfrancia"],"graphOnly":false,"shortTitle":"East Francia","parent":null,"category":"history","posterLabels":["East Francia"],"start":843,"end":962,"ongoing":false},{"id":"poster-europe-096","title":"Margraviate of Austria","shortTitle":"Margraviate of Austria","region":"europe","dates":"976 AD–1156 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Babenberg march was established in 976 and elevated to a duchy in 1156. This was a frontier territory within a wider imperial framework, not an independent modern Austria.","wikiTitle":"Margraviate of Austria","parent":null,"category":"history","sources":["poster_poster-europe-096_0","poster_poster-europe-096_1","wikipedia_poster-europe-096"],"posterLabels":["Margraviate of Austria"],"start":976,"end":1156,"ongoing":false,"graphOnly":false},{"id":"poster-europe-097","title":"Duchy of Austria","shortTitle":"Duchy of Austria","region":"europe","dates":"1156 AD–1453 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Privilegium Minus elevated the march to a duchy in 1156. The archducal title was invented in the fourteenth century but officially recognised in 1453.","wikiTitle":"Duchy of Austria","parent":null,"category":"history","sources":["poster_poster-europe-097_0","poster_poster-europe-097_1","poster_poster-europe-097_2","wikipedia_poster-europe-097"],"posterLabels":["Duchy of Austria"],"start":1156,"end":1453,"ongoing":false,"graphOnly":false},{"id":"poster-europe-098","title":"Habsburg Austria · archducal and composite monarchy phases","shortTitle":"Habsburg Austria","region":"europe","dates":"1453 AD–1804 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"1453 marks formal recognition of the archducal title, not the beginning of Habsburg rule in Austria (which dates to the late thirteenth century). The wider Habsburg monarchy accumulated distinct crowns and territories.","wikiTitle":"Habsburg monarchy","parent":null,"category":"history","sources":["poster_poster-europe-098_0","poster_poster-europe-098_1","poster_poster-europe-098_2","wikipedia_poster-europe-098"],"posterLabels":["Habsburg Austria"],"start":1453,"end":1804,"ongoing":false,"graphOnly":false},{"id":"poster-europe-099","title":"Austrian Empire","shortTitle":"Austrian Empire","region":"europe","dates":"1804 AD–1867 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The Austrian imperial title was proclaimed in 1804, while the Holy Roman Empire still existed until 1806. The Dual Monarchy replaced this framework in 1867.","wikiTitle":"Austrian Empire","parent":null,"category":"history","sources":["poster_poster-europe-099_0","poster_poster-europe-099_1","wikipedia_poster-europe-099"],"posterLabels":["Austrian Empire"],"start":1804,"end":1867,"ongoing":false,"graphOnly":false},{"id":"poster-europe-100","title":"Austria-Hungary","shortTitle":"Austria-Hungary","region":"europe","dates":"1867 AD–1918 AD","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"The 1867 Compromise established a dual monarchy with separate Austrian and Hungarian institutions and shared affairs. Its dissolution in 1918 produced several successor states, not simply modern Austria.","wikiTitle":"Austria-Hungary","parent":null,"category":"history","sources":["poster_poster-europe-100_0","wikipedia_poster-europe-100"],"posterLabels":["Austria-Hungary"],"start":1867,"end":1918,"ongoing":false,"graphOnly":false},{"id":"austriamodern","title":"Austria · modern republican eras","shortTitle":"Austria","region":"europe","dates":"1918 AD–present","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"A modern country frame covering the First Republic, authoritarian Federal State, Nazi annexation, restored republic and Allied occupation. Full sovereignty was restored in 1955, not the first existence of the republic.","wikiTitle":"History of Austria","parent":null,"category":"history","sources":["poster_austriamodern_0","wikipedia_austriamodern"],"posterLabels":["Austria"],"start":1918,"end":2027,"ongoing":true,"graphOnly":false},{"id":"greecemodern","title":"Greece · modern state eras","shortTitle":"Greece","region":"europe","dates":"1830 AD–present","type":"Political or archaeological frame","status":"Contextual","location":"Europe","summary":"","note":"Independence was internationally recognised in 1830 and the kingdom established in 1832. The democratic Third Republic dates to 1974, with its constitution in 1975; the poster’s 1973 marker refers to a junta-controlled abolition of monarchy.","wikiTitle":"History of modern Greece","parent":null,"category":"history","sources":["poster_greecemodern_0","poster_greecemodern_1","wikipedia_greecemodern"],"posterLabels":["Greece"],"start":1830,"end":2027,"ongoing":true,"graphOnly":false},{"id":"cn-ptolemaic","title":"Ptolemaic Kingdom","region":"africa","dates":"305–30 BC","wikiTitle":"Ptolemaic Kingdom","location":"Africa","note":"A Hellenistic kingdom based in Egypt. The royal title dates to 305 BC; Ptolemy had governed Egypt earlier.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-ptolemaic_0","wikipedia_cn-ptolemaic"],"graphOnly":false,"shortTitle":"Ptolemaic Kingdom","parent":null,"category":"history","posterLabels":["Ptolemaic Kingdom"],"start":-305,"end":-30,"ongoing":false},{"id":"fatimid","title":"Fatimid Caliphate","shortTitle":"Fatimid Caliphate","region":"africa","dates":"909 AD–1171 AD","type":"Political or archaeological frame","status":"Contextual","location":"Africa","summary":"","note":"Founded in North Africa 909; conquest of Egypt and establishment of Cairo occurred 969. The poster’s 969 start represents the Egyptian phase, not the caliphate’s founding.","wikiTitle":"Fatimid Caliphate","parent":null,"category":"history","sources":["poster_fatimid_0","wikipedia_fatimid"],"posterLabels":["Fatimid Caliphate"],"start":909,"end":1171,"ongoing":false,"graphOnly":false},{"id":"ayyubid","title":"Ayyubid Sultanate","shortTitle":"Ayyubid Sultanate","region":"africa","dates":"1171 AD–1260 AD","type":"Political or archaeological frame","status":"Contextual","location":"Africa","summary":"","note":"Ayyubid government ended in Egypt 1250; regional Ayyubid rulers in Syria continued through 1260 and some local branches longer. Use 1171–1250 for a strictly Egyptian subperiod.","wikiTitle":"Ayyubid dynasty","parent":null,"category":"history","sources":["poster_ayyubid_0","wikipedia_ayyubid"],"posterLabels":["Ayyubid Sultanate"],"start":1171,"end":1260,"ongoing":false,"graphOnly":false},{"id":"mamluk","title":"Mamluk Sultanate · Egypt and Syria","shortTitle":"Mamluk Sultanate","region":"africa","dates":"1250 AD–1517 AD","type":"Political or archaeological frame","status":"Contextual","location":"Africa","summary":"","note":"Egyptian rule began 1250; control of Syria expanded by 1260. Ottoman conquest 1516–1517 ended the sultanate, although Mamluk elites persisted.","wikiTitle":"Mamluk Sultanate","parent":null,"category":"history","sources":["poster_mamluk_0","wikipedia_mamluk"],"posterLabels":["Mamluk Sultanate"],"start":1250,"end":1517,"ongoing":false,"graphOnly":false},{"id":"muhammad-ali","title":"Egypt · Muhammad Ali dynasty","shortTitle":"Muhammad Ali dynasty","region":"africa","dates":"1805 AD–1953 AD","type":"Political or archaeological frame","status":"Contextual","location":"Africa","summary":"","note":"The dynasty continued across the British occupation, protectorate and Kingdom of Egypt; these were overlapping political dimensions. The poster cuts the dynasty at 1882.","wikiTitle":"Muhammad Ali dynasty","parent":null,"category":"history","sources":["poster_muhammad-ali_0","poster_muhammad-ali_1","wikipedia_muhammad-ali"],"posterLabels":["Muhammad Ali Dynasty"],"start":1805,"end":1953,"ongoing":false,"graphOnly":false},{"id":"neo-hittite","title":"Syro-Hittite / Neo-Hittite kingdoms","shortTitle":"Neo-Hittite Kingdoms","region":"westasia","dates":"1180 BC–700 BC","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Multiple Luwian and Aramaean kingdoms followed the Hittite imperial collapse; no single successor empire. Final incorporation into Assyria varied by kingdom.","wikiTitle":"Neo-Hittite states","parent":null,"category":"history","sources":["poster_neo-hittite_0","wikipedia_neo-hittite"],"posterLabels":["Neo-Hittite Kingdoms"],"start":-1180,"end":-700,"ongoing":false,"graphOnly":false},{"id":"lydia","title":"Lydia · Mermnad kingdom","shortTitle":"Kingdom of Lydia","region":"westasia","dates":"680 BC–546 BC","type":"Political or archaeological frame","status":"Debated","location":"West Asia","summary":"","note":"Selected well-attested Mermnad phase begins around 680 BC. Earlier Lydian traditions and rulers predate it; Cyrus’s conquest is conventionally dated 547/546 BC.","wikiTitle":"Lydia","parent":null,"category":"history","sources":["poster_lydia_0","wikipedia_lydia"],"posterLabels":["Kingdom of Lydia"],"start":-680,"end":-546,"ongoing":false,"graphOnly":false},{"id":"sumer","title":"Sumer · cities and writing","shortTitle":"Sumer","region":"westasia","dates":"4000 BC–2004 BC","type":"Political or archaeological frame","status":"Debated","location":"West Asia","summary":"","note":"Selected urban Sumerian cultural history, not a single united empire. The poster’s 4500 BC start is an overly precise ethnic-cultural founding date: Ubaid settlement traditions are earlier, while Uruk urbanization and writing developed during the fourth millennium. Ur III ended 2004 BC; Sumerian language and traditions persisted.","wikiTitle":"Sumer","parent":null,"category":"history","sources":["poster_sumer_0","poster_sumer_1","wikipedia_sumer"],"posterLabels":["Sumerian Civilization"],"start":-4000,"end":-2004,"ongoing":false,"graphOnly":false},{"id":"middle-assyrian","title":"Assyria · Middle Assyrian period","shortTitle":"Assyrian Empire","region":"westasia","dates":"1365 BC–911 BC","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"The poster’s broad Assyrian band combines Middle and Neo-Assyrian periods. This earlier phase complements existing Neo-Assyria; power and territory fluctuated.","wikiTitle":"Middle Assyrian Empire","parent":null,"category":"history","sources":["poster_middle-assyrian_0","wikipedia_middle-assyrian"],"posterLabels":["Assyrian Empire"],"start":-1365,"end":-911,"ongoing":false,"graphOnly":false},{"id":"neo-babylonian","title":"Neo-Babylonian Empire","shortTitle":"Neo-Babylonian Empire","region":"westasia","dates":"626 BC–539 BC","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Nabopolassar’s kingdom began 626 BC; imperial expansion followed Assyria’s collapse 612–609. Conquered by Cyrus 539 BC.","wikiTitle":"Neo-Babylonian Empire","parent":null,"category":"history","sources":["poster_neo-babylonian_0","wikipedia_neo-babylonian"],"posterLabels":["Neo-Babylonian Empire"],"start":-626,"end":-539,"ongoing":false,"graphOnly":false},{"id":"elam","title":"Elam · kingdoms of southwest Iran","shortTitle":"Elamite Civilization","region":"westasia","dates":"2700 BC–539 BC","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"A sequence of kingdoms and cultural phases, not one uninterrupted empire. Elamite history did not simply end 1500 BC with the appearance of Iranian-speaking groups; these histories overlapped.","wikiTitle":"Elam","parent":null,"category":"history","sources":["poster_elam_0","poster_elam_1","poster_elam_2","wikipedia_elam"],"posterLabels":["Elamite Civilization"],"start":-2700,"end":-539,"ongoing":false,"graphOnly":false},{"id":"early-iranian-peoples","title":"Early Iranian-speaking peoples","shortTitle":"Iranian Tribes","region":"westasia","dates":"1500 BC–550 BC","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"A selected approximate pre-Achaemenid frame, not a state or a single dated migration. Western-Iranian groups are securely attested in Assyrian records by the ninth centuryBCE; their languages and societies continued after 550 BC.","wikiTitle":"Iranian peoples","parent":null,"category":"history","sources":["poster_early-iranian-peoples_0","wikipedia_early-iranian-peoples"],"posterLabels":["Iranian Tribes"],"start":-1500,"end":-550,"ongoing":false,"graphOnly":false},{"id":"medes","title":"Medes · kingdom and debated empire","shortTitle":"Medes","region":"westasia","dates":"678 BC–550 BC","type":"Political or archaeological frame","status":"Debated","location":"West Asia","summary":"","note":"Conventional traditional frame only. The extent, political unity and chronology of a Median empire remain debated; no claim that a securely documented empire was founded in 678 BC.","wikiTitle":"Medes","parent":null,"category":"history","sources":["poster_medes_0","poster_medes_1","wikipedia_medes"],"posterLabels":["Median Empire"],"start":-678,"end":-550,"ongoing":false,"graphOnly":false},{"id":"cn-alexander","title":"Alexander’s empire","region":"europe","dates":"334–323 BC · conquest phase","wikiTitle":"Alexander the Great","location":"Europe","note":"This selects the period of expansion into the Achaemenid realm. Alexander became king in 336 BC; successor kingdoms emerged through prolonged wars after his death.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-alexander_0","wikipedia_cn-alexander"],"graphOnly":false,"shortTitle":"Macedon","parent":null,"category":"history","posterLabels":["Macedonian Empire"],"start":-334,"end":-323,"ongoing":false},{"id":"cn-seleucid","title":"Seleucid Empire","region":"westasia","dates":"312–63 BC","wikiTitle":"Seleucid Empire","location":"West Asia","note":"One of several Hellenistic successor kingdoms. Its territory contracted over time, and it did not encompass all of Alexander’s former realm.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-seleucid_0","wikipedia_cn-seleucid"],"graphOnly":false,"shortTitle":"Seleucid Empire","parent":null,"category":"history","posterLabels":["Seleucid Empire"],"start":-312,"end":-63,"ongoing":false},{"id":"cn-parthian","title":"Parthian Empire","region":"westasia","dates":"247 BC–224 AD","wikiTitle":"Parthian Empire","location":"West Asia","note":"Parthian rulers expanded gradually into Seleucid-held territories and were later overthrown by the Sasanians.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-parthian_0","wikipedia_cn-parthian"],"graphOnly":false,"shortTitle":"Parthian Empire","parent":null,"category":"history","posterLabels":["Parthian Empire"],"start":-247,"end":224,"ongoing":false},{"id":"sultanate-rum","title":"Sultanate of Rûm","shortTitle":"Sultanate of Rum","region":"westasia","dates":"1077 AD–1308 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"An Anatolian Seljuk state distinct from the Great Seljuq Empire already in the chart. Autonomy weakened after defeat by the Mongols 1243.","wikiTitle":"Sultanate of Rum","parent":null,"category":"history","sources":["poster_sultanate-rum_0","wikipedia_sultanate-rum"],"posterLabels":["Sultanate of Rum"],"start":1077,"end":1308,"ongoing":false,"graphOnly":false},{"id":"post-abbasid-dynasties","title":"Iran and Iraq · Mongol and regional dynasties","shortTitle":"Post-Abbasid Regional Dynasties","region":"westasia","dates":"1258 AD–1501 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"A regional overview, not a single successor state. Includes Ilkhanid, Jalayirid, Timurid and Turkmen powers with different and overlapping dates; Ilkhanid rule began before 1258 and several regional histories continued after 1501.","wikiTitle":"History of Iran","parent":null,"category":"history","sources":["poster_post-abbasid-dynasties_0","wikipedia_post-abbasid-dynasties"],"posterLabels":["Post-Abbasid Regional Dynasties"],"start":1258,"end":1501,"ongoing":false,"graphOnly":false},{"id":"cn-ilkhanate","title":"Ilkhanate","region":"westasia","dates":"1256–1335 AD · united dynasty","wikiTitle":"Ilkhanate","location":"West Asia","note":"A regional Mongol khanate. The united dynasty fragmented in 1335; later claimants and successor states continued. Some art chronologies extend to 1353.","summary":"","status":"Contextual","type":"Political or archaeological frame","sources":["poster_cn-ilkhanate_0","wikipedia_cn-ilkhanate"],"graphOnly":false,"shortTitle":"Ilkhanate","parent":null,"category":"history","posterLabels":["Post-Abbasid Regional Dynasties"],"start":1256,"end":1335,"ongoing":false},{"id":"timurid","title":"Timurid Empire","shortTitle":"Timurid Empire","region":"westasia","dates":"1370 AD–1507 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Specific major power within the poster’s umbrella band; western Iranian territory also passed to Turkmen dynasties. Their dates do not define a single 1258–1501 empire.","wikiTitle":"Timurid Empire","parent":null,"category":"history","sources":["poster_timurid_0","wikipedia_timurid"],"posterLabels":["Post-Abbasid Regional Dynasties"],"start":1370,"end":1507,"ongoing":false,"graphOnly":false},{"id":"afsharid","title":"Afsharid Iran","shortTitle":"Afsharid Empire","region":"westasia","dates":"1736 AD–1796 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Nader Shah’s empire fragmented after his death 1747. Afsharid government in Khorasan survived until 1796, overlapping the Zands and rising Qajars.","wikiTitle":"Afsharid Iran","parent":null,"category":"history","sources":["poster_afsharid_0","wikipedia_afsharid"],"posterLabels":["Afsharid Empire"],"start":1736,"end":1796,"ongoing":false,"graphOnly":false},{"id":"qajar","title":"Qajar Iran","shortTitle":"Qajar Dynasty","region":"westasia","dates":"1789 AD–1925 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Start dates 1786,1789,1794 and 1796 reflect different stages of consolidation and coronation. Use conventional 1789 for the dynasty and explain 1796 coronation; the poster selects 1796.","wikiTitle":"Qajar Iran","parent":null,"category":"history","sources":["poster_qajar_0","poster_qajar_1","wikipedia_qajar"],"posterLabels":["Qajar Dynasty"],"start":1789,"end":1925,"ongoing":false,"graphOnly":false},{"id":"iraq-kingdom","title":"Kingdom of Iraq","shortTitle":"Kingdom of Iraq","region":"westasia","dates":"1921 AD–1958 AD","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"Monarchy established 1921 under British control; mandate ended and independence recognized 1932. Monarchy overthrown 14 July 1958.","wikiTitle":"Kingdom of Iraq","parent":null,"category":"history","sources":["poster_iraq-kingdom_0","wikipedia_iraq-kingdom"],"posterLabels":["Kingdom of Iraq"],"start":1921,"end":1958,"ongoing":false,"graphOnly":false},{"id":"iraqmodern","title":"Iraq · republican eras","shortTitle":"Iraq","region":"westasia","dates":"1958 AD–present","type":"Political or archaeological frame","status":"Contextual","location":"West Asia","summary":"","note":"A succession of republics and regimes, with major changes 1968,2003 and 2005. The state and Iraqi society did not originate 1958.","wikiTitle":"Iraq","parent":null,"category":"history","sources":["poster_iraqmodern_0","wikipedia_iraqmodern"],"posterLabels":["Iraq"],"start":1958,"end":2027,"ongoing":true,"graphOnly":false},{"id":"mahajanapadas","title":"Mahājanapadas","shortTitle":"Mahajanapadas","region":"southasia","dates":"600 BC–322 BC","type":"Political or archaeological frame","status":"Contextual","location":"South Asia","summary":"","note":"Multiple kingdoms and oligarchic republics, principally in northern South Asia; conventional sixth–fourth centuryBCE frame. Mauryan expansion incorporated different states at different times.","wikiTitle":"Mahajanapadas","parent":null,"category":"history","sources":["poster_mahajanapadas_0","wikipedia_mahajanapadas"],"posterLabels":["Mahajanapadas"],"start":-600,"end":-322,"ongoing":false,"graphOnly":false},{"id":"post-mauryan","title":"Post-Mauryan South Asian kingdoms","shortTitle":"Post-Mauryan Kingdoms","region":"southasia","dates":"185 BC–320 AD","type":"Political or archaeological frame","status":"Contextual","location":"South Asia","summary":"","note":"Period overview containing Shunga, Kanva, Indo-Greek, Shaka, Satavahana and Kushan powers; many coexisted. Existing Kushan history provides one named example.","wikiTitle":"History of India","parent":null,"category":"history","sources":["poster_post-mauryan_0","wikipedia_post-mauryan"],"posterLabels":["Post-Mauryan Kingdoms"],"start":-185,"end":320,"ongoing":false,"graphOnly":false},{"id":"post-gupta","title":"Post-Gupta regional kingdoms","shortTitle":"Post-Gupta Kingdoms","region":"southasia","dates":"550 AD–647 AD","type":"Political or archaeological frame","status":"Debated","location":"South Asia","summary":"","note":"A selected transition frame, not one polity. Regional kingdoms and post-Gupta artistic traditions began before and continued after Harsha; avoid a blanket replacement at 606.","wikiTitle":"Middle kingdoms of India","parent":null,"category":"history","sources":["poster_post-gupta_0","poster_post-gupta_1","wikipedia_post-gupta"],"posterLabels":["Post-Gupta Kingdoms"],"start":550,"end":647,"ongoing":false,"graphOnly":false},{"id":"harsha","title":"Harsha · northern Indian kingdom","shortTitle":"Harsha’s Empire","region":"southasia","dates":"606 AD–647 AD","type":"Political or archaeological frame","status":"Contextual","location":"South Asia","summary":"","note":"Harsha ruled parts of northern India 606–647, not all South Asia; southern powers including the Chalukyas remained independent.","wikiTitle":"Harsha","parent":null,"category":"history","sources":["poster_harsha_0","wikipedia_harsha"],"posterLabels":["Harsha’s Empire"],"start":606,"end":647,"ongoing":false,"graphOnly":false},{"id":"india-regional-kingdoms","title":"Early medieval South Asian kingdoms","shortTitle":"Regional Kingdoms","region":"southasia","dates":"647 AD–1206 AD","type":"Political or archaeological frame","status":"Contextual","location":"South Asia","summary":"","note":"A broad selected frame, not one state or a cultural vacuum. Includes Pala, Pratihara, Rashtrakuta, Chalukya, Chola and Rajput polities with overlapping dates; southern kingdoms continued after 1206.","wikiTitle":"Middle kingdoms of India","parent":null,"category":"history","sources":["poster_india-regional-kingdoms_0","wikipedia_india-regional-kingdoms"],"posterLabels":["Regional Kingdoms"],"start":647,"end":1206,"ongoing":false,"graphOnly":false},{"id":"xia","title":"Xia · traditional dynasty, debated identification","shortTitle":"Xia Dynasty","region":"eastasia","dates":"2070 BC–1600 BC","type":"Political or archaeological frame","status":"Debated","location":"East Asia","summary":"","note":"These are traditional/modelled dates, not secure contemporary attestations. No surviving contemporary inscription securely identifies Erlitou as Xia; historicity and archaeological identification remain debated.","wikiTitle":"Xia dynasty","parent":null,"category":"history","sources":["poster_xia_0","poster_xia_1","wikipedia_xia"],"posterLabels":["Xia Dynasty"],"start":-2070,"end":-1600,"ongoing":false,"graphOnly":false},{"id":"china-division","title":"China · Six Dynasties and divided realms","shortTitle":"Age of Division","region":"eastasia","dates":"220 AD–589 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"An umbrella period, not one government. Includes Three Kingdoms, Western/Eastern Jin, Sixteen Kingdoms and Northern/Southern dynasties; brief Western Jin reunification 280–316 interrupts any claim of continuous division.","wikiTitle":"Six Dynasties","parent":null,"category":"history","sources":["poster_china-division_0","wikipedia_china-division"],"posterLabels":["Age of Division"],"start":220,"end":589,"ongoing":false,"graphOnly":false},{"id":"five-dynasties","title":"Five Dynasties and Ten Kingdoms","shortTitle":"Five Dynasties","region":"eastasia","dates":"907 AD–979 AD","type":"Political or archaeological frame","status":"Debated","location":"East Asia","summary":"","note":"Northern Five Dynasties traditionally end 960 with Song’s foundation, while southern independent kingdoms continued until 979. A network of concurrent states, not five rulers of all China.","wikiTitle":"Five Dynasties and Ten Kingdoms period","parent":null,"category":"history","sources":["poster_five-dynasties_0","poster_five-dynasties_1","wikipedia_five-dynasties"],"posterLabels":["Five Dynasties Period"],"start":907,"end":979,"ongoing":false,"graphOnly":false},{"id":"jomon","title":"Jōmon period","shortTitle":"Jōmon Period","region":"eastasia","dates":"13000 BC–300 BC","type":"Political or archaeological frame","status":"Debated","location":"East Asia","summary":"","note":"Starts many millennia before the chart window. The transition to Yayoi was regionally gradual from roughly 900 BC; Jōmon traditions persisted later in northern areas. This is not Japan’s first human occupation.","wikiTitle":"Jōmon period","parent":null,"category":"history","sources":["poster_jomon_0","poster_jomon_1","wikipedia_jomon"],"posterLabels":["Jōmon Period"],"start":-13000,"end":-300,"ongoing":false,"graphOnly":false},{"id":"yayoi","title":"Yayoi period","shortTitle":"Yayoi Period","region":"eastasia","dates":"900 BC–250 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"Dates vary by region and dating method. Newer chronologies place wet-rice-based Yayoi society from around 900 BC in northern Kyushu, while older general surveys use 300 BC. Do not present the poster’s 300 BC as a universal secure start.","wikiTitle":"Yayoi period","parent":null,"category":"history","sources":["poster_yayoi_0","poster_yayoi_1","wikipedia_yayoi"],"posterLabels":["Yayoi Period"],"start":-900,"end":250,"ongoing":false,"graphOnly":false},{"id":"yamato","title":"Yamato polity · Kofun and Asuka periods","shortTitle":"Yamato State","region":"eastasia","dates":"250 AD–710 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"A broad conventional Kofun/Asuka frame; the Yamato court consolidated gradually.250 is an archaeological-period anchor, not a known single state-founding date.","wikiTitle":"Yamato period","parent":null,"category":"history","sources":["poster_yamato_0","wikipedia_yamato"],"posterLabels":["Yamato State"],"start":250,"end":710,"ongoing":false,"graphOnly":false},{"id":"nara","title":"Nara period","shortTitle":"Nara Period","region":"eastasia","dates":"710 AD–794 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"Capital established at Heijō-kyō710; court moved to Heian-kyō794, with a brief intervening Nagaoka phase 784–794.","wikiTitle":"Nara period","parent":null,"category":"history","sources":["poster_nara_0","wikipedia_nara"],"posterLabels":["Nara Period"],"start":710,"end":794,"ongoing":false,"graphOnly":false},{"id":"kamakura","title":"Kamakura shogunate","shortTitle":"Kamakura Shogunate","region":"eastasia","dates":"1185 AD–1333 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"1185 marks military victory and establishment of rule;1192 marks Minamoto no Yoritomo’s shogunal title. Shogunate ended 1333.","wikiTitle":"Kamakura shogunate","parent":null,"category":"history","sources":["poster_kamakura_0","wikipedia_kamakura"],"posterLabels":["Kamakura Shogunate"],"start":1185,"end":1333,"ongoing":false,"graphOnly":false},{"id":"muromachi","title":"Muromachi / Ashikaga shogunate","shortTitle":"Muromachi Shogunate","region":"eastasia","dates":"1336 AD–1573 AD","type":"Political or archaeological frame","status":"Contextual","location":"East Asia","summary":"","note":"Ashikaga regime 1336–1573, with a rival Southern Court 1336–1392. The later Sengoku wars overlap it; the shogunate did not continue to 1603.","wikiTitle":"Ashikaga shogunate","parent":null,"category":"history","sources":["poster_muromachi_0","poster_muromachi_1","wikipedia_muromachi"],"posterLabels":["Muromachi Shogunate"],"start":1336,"end":1573,"ongoing":false,"graphOnly":false},{"id":"poster-newspain","title":"New Spain · mainland Mexican frame","shortTitle":"Colonial Era","region":"americas","dates":"1521–1821 AD · conquest and colonial frame","type":"Political or archaeological frame","status":"Contextual","location":"The Americas","summary":"","note":"1521 marks the fall of Tenochtitlan; the Viceroyalty of New Spain was established in 1535. Its jurisdiction extended far beyond present-day Mexico and changed over time. Spanish conquest did not end Indigenous peoples or cultures.","wikiTitle":"New Spain","parent":"spanishamerica","category":"history","sources":["wikipedia_poster-newspain"],"posterLabels":["Colonial Era · Mexico"],"start":1521,"end":1821,"ongoing":false,"graphOnly":false},{"id":"poster-colonial-argentina","title":"Spanish colonial Río de la Plata","shortTitle":"Colonial Era","region":"americas","dates":"1536–1816 AD · selected regional frame","type":"Political or archaeological frame","status":"Contextual","location":"The Americas","summary":"","note":"1536 marks the first, short-lived Buenos Aires settlement, not continuous control of present-day Argentina. The second foundation was in 1580. The Viceroyalty of the Río de la Plata existed only from 1776, and the independence process began in 1810 before the 1816 declaration. Indigenous territories were not uniformly controlled.","wikiTitle":"Viceroyalty of the Río de la Plata","parent":"spanishamerica","category":"history","sources":["poster_poster-colonial-argentina_0","wikipedia_poster-colonial-argentina"],"posterLabels":["Colonial Era · Argentina"],"start":1536,"end":1816,"ongoing":false,"graphOnly":false},{"id":"poster-colonial-australia","title":"Australia · British colonial periods","shortTitle":"Colonial Australia","region":"oceania","dates":"1788–1901 AD · multiple colonies","type":"Political or archaeological frame","status":"Contextual","location":"Oceania","summary":"","note":"The British colony of New South Wales began in 1788; other colonies were established or separated later. Six colonies federated in 1901. Colonial expansion involved dispossession and conflict, while Aboriginal and Torres Strait Islander histories continued.","wikiTitle":"History of Australia (1788–1850)","parent":"australiamodern","category":"history","sources":["poster_poster-colonial-australia_0","poster_poster-colonial-australia_1","wikipedia_poster-colonial-australia"],"posterLabels":["Colonial Australia"],"start":1788,"end":1901,"ongoing":false,"graphOnly":false},{"id":"argentinamodern","title":"Argentina · independent eras","shortTitle":"Argentina","region":"americas","dates":"1816 AD–present","type":"Political or archaeological frame","status":"Contextual","location":"The Americas","summary":"","note":"1816 marks the declaration of independence by the United Provinces, following the 1810 revolution. The Argentine state, its constitutional arrangements and territorial control developed through later conflicts and agreements. This is not an unchanged republic from 1816.","wikiTitle":"History of Argentina","parent":null,"category":"history","sources":["poster_argentinamodern_0","wikipedia_argentinamodern"],"posterLabels":["Argentina"],"start":1816,"end":2027,"ongoing":true,"graphOnly":false},{"id":"israel-samaria","title":"Kingdom of Israel (Samaria)","shortTitle":"Northern Israel","category":"history","start":-900,"end":-722,"year":-900,"dates":"c. 9th century–722/721 BC","wikiTitle":"Kingdom of Israel (Samaria)","region":"westasia","location":"Southern Levant and wider Jewish communities","type":"Selected political frame","status":"Approximate","summary":"A northern Israelite kingdom, with its later capital at Samaria. Assyrian conquest ended the kingdom and deported part of its population.","note":"The 900 BC start is an approximate display anchor for early state development, not a documented founding year. Origins, early chronology and the relationship with Judah remain debated. This is the ancient northern kingdom, distinct from modern Israel.","sources":["supplement_jewishKingdoms","supplement_israelJudah","wikipedia_israel-samaria"],"searchAliases":["Israelites","ancient Israel","Samaria","Jewish history","Jews"]},{"id":"judah","title":"Kingdom of Judah","shortTitle":"Judah","category":"history","start":-900,"end":-586,"year":-900,"dates":"c. 9th century–587/586 BC","wikiTitle":"Kingdom of Judah","region":"westasia","location":"Southern Levant and wider Jewish communities","type":"Selected political frame","status":"Approximate","summary":"A southern Israelite kingdom centred on Jerusalem, important to the development of Jewish history and traditions. Babylonian conquest destroyed Jerusalem and its temple and deported many inhabitants; others remained.","note":"The 900 BC start is an approximate display anchor, not an established founding date. The emergence of the kingdom and its relationship with northern Israel are debated. The fall of its government did not end Jewish communities or traditions.","sources":["supplement_jewishKingdoms","supplement_israelJudah","wikipedia_judah"],"searchAliases":["Jews","Jewish history","Judeans","Jerusalem","Babylonian exile"]},{"id":"hasmonean-judea","title":"Hasmonean Judea","shortTitle":"Hasmonean Judea","category":"history","start":-140,"end":-37,"year":-140,"dates":"c. 140–37 BC","wikiTitle":"Hasmonean Judea","region":"westasia","location":"Southern Levant and wider Jewish communities","type":"Selected political frame","status":"Conventional","summary":"Jewish rulers established an expanding Judean state during the Hellenistic period. Roman intervention reduced its independence before Herod took Jerusalem in 37 BC.","note":"The 140 BC start is a conventional dynastic-period boundary. The Maccabean revolt began earlier; Roman intervention in 63 BC curtailed sovereignty before the dynasty ended. This block does not represent all Jewish communities.","sources":["supplement_hasmonean","supplement_jewishKingdoms","wikipedia_hasmonean-judea"],"searchAliases":["Jews","Jewish history","Maccabees","Judea"]}]);
